//! `COVERAGE.md`, the human view of `coverage.json`.

use std::collections::BTreeMap;
use std::fmt::Write;

use crate::compute::{Coverage, FragmentRow, Reason};
use crate::uncovered::Blocker;

// a fragment row lists this many entry ids before it falls back to a count
const FRAGMENT_EXAMPLES: usize = 3;

pub fn render(c: &Coverage) -> String {
    let mut out = String::new();
    let s = &c.summary;
    out.push_str("# Corpus coverage\n\n");
    let _ = writeln!(
        out,
        "Generated by `shapekit coverage` from `corpus/manifest.json` (corpus {}, stellar-xdr {}) and `registry/`. Do not edit by hand; `shapekit coverage --check` fails when this file is stale.\n",
        c.corpus_version, c.stellar_xdr
    );
    out.push_str(
        "Only core-emitted entries count as coverage: `core-golden`, `local-core`, `testnet-history` and `mainnet-history` entries whose bytes core wrote into a ledger, and `core-test-dump` entries, the transaction meta core's own tests wrote. Synthetic entries and envelopes core refused at submission (`local-core-refused`) are listed next to a gap as evidence of the shape, never as coverage. Every gap carries a one-line reason from `registry/uncovered.toml`.\n\n",
    );

    out.push_str("## Summary\n\n| Measure | Value |\n|---|---|\n");
    let rows: Vec<(String, String)> = vec![
        ("Entries".into(), s.entries.to_string()),
        (
            "Core-emitted entries".into(),
            s.core_emitted_entries.to_string(),
        ),
        (
            "Entries by source class".into(),
            counts(&s.entries_by_source_class),
        ),
        (
            "CAPs (indexer-visible)".into(),
            format!("{} ({})", s.caps, s.caps_indexer_visible),
        ),
        (
            "Indexer-visible CAPs with a core-emitted entry".into(),
            s.caps_indexer_visible_core_emitted.to_string(),
        ),
        (
            "Indexer-visible CAPs uncovered, with a reason".into(),
            s.caps_indexer_visible_with_reason.to_string(),
        ),
        (
            format!("Union arms reachable from `{}`", c.root_type),
            s.arms_reachable.to_string(),
        ),
        (
            "Arms covered by a core-emitted entry".into(),
            format!(
                "{} ({})",
                s.arms_covered,
                percent(s.arms_covered, s.arms_reachable)
            ),
        ),
        ("Arms uncovered".into(), s.arms_uncovered.to_string()),
        (
            "Uncovered arms by blocker".into(),
            s.arms_uncovered_by_blocker
                .iter()
                .map(|(b, n)| format!("{} {n}", blocker(*b)))
                .collect::<Vec<_>>()
                .join(", "),
        ),
        (
            "Family fragments covered".into(),
            format!(
                "{} of {} in {} families",
                s.fragments_covered, s.fragments, s.families
            ),
        ),
        (
            "Fields core does not fully validate, exercised".into(),
            format!(
                "{} of {}",
                s.fields_not_fully_validated_exercised, s.fields_not_fully_validated
            ),
        ),
    ];
    for (k, v) in rows {
        let _ = writeln!(out, "| {} | {} |", cell(&k), cell(&v));
    }

    out.push_str("\n## Blockers\n\n| Blocker | Meaning |\n|---|---|\n");
    for (b, meaning) in [
        (
            Blocker::RefusedBeforeLedger,
            "core refuses the transaction before it reaches a ledger; the arm exists only in a submit-time result",
        ),
        (
            Blocker::OldProtocolOnly,
            "only ledgers below some protocol carry it; no recipe records a chain that old and no history capture holds it",
        ),
        (
            Blocker::HistoryOnly,
            "only a public network can hold it and no capture exists yet",
        ),
        (
            Blocker::NotProducibleLocally,
            "the pinned core has the code path but a private standalone network cannot reach it",
        ),
        (
            Blocker::NeverEmitted,
            "the pinned core has no code path that produces it",
        ),
        (
            Blocker::NotImported,
            "the core goldens hold it, but the importer takes one golden per family fragment and no fragment names it",
        ),
        (
            Blocker::RecipeGap,
            "a local core can produce it and no recipe records it yet",
        ),
    ] {
        let _ = writeln!(out, "| `{}` | {meaning} |", blocker(b));
    }

    caps(&mut out, c);
    arms(&mut out, c);
    families(&mut out, c);
    fields(&mut out, c);
    out
}

fn caps(out: &mut String, c: &Coverage) {
    out.push_str("\n## Per CAP\n\n");
    out.push_str("| CAP | Protocol | Indexer-visible | Families | Entries | Core-emitted | By source class | By variant | Core-emitted protocols | Note |\n");
    out.push_str("|---|---|---|---|---|---|---|---|---|---|\n");
    for cap in &c.caps {
        let note = if let Some(r) = &cap.uncovered {
            reason(r)
        } else if let Some(r) = &cap.not_visible_reason {
            r.clone()
        } else {
            String::new()
        };
        let _ = writeln!(
            out,
            "| {} {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |",
            cap.id,
            cell(&cap.title),
            cap.protocol.map(|p| p.to_string()).unwrap_or_default(),
            if cap.indexer_visible { "yes" } else { "no" },
            code_list(&cap.families),
            cap.entries,
            cap.core_emitted_entries,
            counts(&cap.entries_by_source_class),
            counts(&cap.entries_by_variant),
            protocols(&cap.protocols_core_emitted),
            cell(&note),
        );
    }
}

fn arms(out: &mut String, c: &Coverage) {
    let a = &c.arms;
    let _ = writeln!(
        out,
        "\n## Union arms reachable from `{}`\n\n{} of {} arms are held by at least one core-emitted entry. The full per-arm counts are in `coverage.json`.\n",
        c.root_type,
        a.covered.len(),
        a.reachable
    );
    out.push_str(
        "### Uncovered arms\n\n| Arm | Blocker | Reason | Shape seen in |\n|---|---|---|---|\n",
    );
    for u in &a.uncovered {
        let (b, r) = match &u.uncovered {
            Some(r) => (format!("`{}`", blocker(r.blocker)), cell(&r.reason)),
            None => ("**none**".into(), "**no reason recorded**".into()),
        };
        let _ = writeln!(
            out,
            "| `{}` | {b} | {r} | {} |",
            u.arm,
            evidence(&u.non_core_entries, &u.refused_by_core)
        );
    }
}

fn families(out: &mut String, c: &Coverage) {
    out.push_str("\n## Family fragments\n\nA fragment is covered when a core-emitted entry of any family matches it.\n");
    for f in &c.families {
        let _ = writeln!(
            out,
            "\n### `{}`\n\n{}. CAPs: {}. Entries: {}.",
            f.id,
            cell(&f.title),
            f.caps.join(", "),
            if f.entries_by_source_class.is_empty() {
                "none".to_string()
            } else {
                counts(&f.entries_by_source_class)
            }
        );
        if !f.missing_source_classes.is_empty() {
            let _ = writeln!(
                out,
                "Expected source classes with no entry: {}.",
                f.missing_source_classes.join(", ")
            );
        }
        out.push_str("\n| Fragment | Core-emitted entries | Gap |\n|---|---|---|\n");
        for frag in &f.fragments {
            let _ = writeln!(
                out,
                "| `{}` | {} | {} |",
                cell(&frag.fragment),
                examples(&frag.core_emitted),
                gap(frag)
            );
        }
        if !f.planned.is_empty() {
            out.push_str("\nPlanned shapes no fragment can express, not in the corpus:\n\n");
            for p in &f.planned {
                let _ = writeln!(out, "- {}: `{}` {}", p.shape, blocker(p.blocker), p.reason);
            }
        }
    }
}

fn fields(out: &mut String, c: &Coverage) {
    if !c.obligations.is_empty() {
        out.push_str("\n## Obligations\n\n");
        out.push_str(
            "Every obligation the corpus owes a witness for, from `corpus/coverage/obligations.json`. That file merges the fragments listed in `registry/obligation-sources.toml`, one `gap` obligation per row of `registry/gaps/`, both sides of every protocol gate in `registry/generated/gates.json`, and the obligations corpus and candidate entries name. An obligation an entry names is met by that entry. A kind with no rows has no producer committed yet.\n\n| Kind | Met | Unmeetable | Open | Total |\n|---|---|---|---|---|\n",
        );
        for r in &c.obligations {
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | {} | {} |",
                r.kind,
                r.met,
                r.unmeetable,
                r.open,
                r.met + r.unmeetable + r.open
            );
        }
    }
    out.push_str("\n## Fields core does not fully validate\n\n| Field | XDR path | Core validates | Entries | Core-emitted | By source class |\n|---|---|---|---|---|---|\n");
    for f in &c.fields {
        let v = match f.validated_by_core {
            shapekit_registry::ValidatedByCore::Yes => "yes",
            shapekit_registry::ValidatedByCore::No => "no",
            shapekit_registry::ValidatedByCore::Partial => "partial",
        };
        let _ = writeln!(
            out,
            "| `{}` | `{}` | {v} | {} | {} | {} |",
            f.id,
            cell(&f.xdr_path),
            f.entries.len(),
            f.core_emitted_entries,
            counts(&f.entries_by_source_class)
        );
    }
}

fn gap(frag: &FragmentRow) -> String {
    if frag.covered {
        return String::new();
    }
    let mut text = match &frag.uncovered {
        Some(r) => reason(r),
        None => "**no reason recorded**".into(),
    };
    let ev = evidence(&frag.non_core_entries, &frag.refused_by_core);
    if !ev.is_empty() {
        let _ = write!(text, " Shape seen in: {ev}");
    }
    cell(&text)
}

fn evidence(non_core: &[String], refused: &[String]) -> String {
    let mut parts = Vec::new();
    if !non_core.is_empty() {
        parts.push(format!("non-core {}", examples(non_core)));
    }
    if !refused.is_empty() {
        parts.push(format!("refused by core {}", examples(refused)));
    }
    parts.join("; ")
}

fn examples(ids: &[String]) -> String {
    if ids.is_empty() {
        return "none".into();
    }
    let shown: Vec<String> = ids
        .iter()
        .take(FRAGMENT_EXAMPLES)
        .map(|i| format!("`{i}`"))
        .collect();
    let more = ids.len().saturating_sub(FRAGMENT_EXAMPLES);
    if more == 0 {
        format!("{}: {}", ids.len(), shown.join(", "))
    } else {
        format!("{}: {} and {more} more", ids.len(), shown.join(", "))
    }
}

fn reason(r: &Reason) -> String {
    format!("`{}` {}", blocker(r.blocker), r.reason)
}

fn blocker(b: Blocker) -> &'static str {
    match b {
        Blocker::RefusedBeforeLedger => "refused-before-ledger",
        Blocker::OldProtocolOnly => "old-protocol-only",
        Blocker::HistoryOnly => "history-only",
        Blocker::NotProducibleLocally => "not-producible-locally",
        Blocker::NeverEmitted => "never-emitted",
        Blocker::NotImported => "not-imported",
        Blocker::RecipeGap => "recipe-gap",
    }
}

fn counts<K: std::fmt::Display>(m: &BTreeMap<K, usize>) -> String {
    m.iter()
        .map(|(k, v)| format!("{k} {v}"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn protocols(p: &[u32]) -> String {
    p.iter().map(u32::to_string).collect::<Vec<_>>().join(", ")
}

fn code_list(items: &[String]) -> String {
    items
        .iter()
        .map(|i| format!("`{i}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn percent(n: usize, d: usize) -> String {
    if d == 0 {
        return "n/a".into();
    }
    // integer tenths keep the text stable across float formatting
    let tenths = (n * 1000 + d / 2) / d;
    format!("{}.{}%", tenths / 10, tenths % 10)
}

// table cells cannot hold a pipe or a newline
fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}
